// Transforma o array de issues em itens individuais do n8n, um por issue,
// pra que o proximo node (GET individual) rode uma vez por issue.
// Se nao houver nenhuma issue elegivel, sinaliza isso explicitamente
// (em vez de simplesmente nao produzir nada), pra permitir liberar a
// trava global mesmo quando nao ha nada pra processar nesta rodada.

const response = $input.first().json;
const issues = response.issues || [];

if (issues.length === 0) {
  return [{ json: { no_eligible_tickets: true } }];
}

return issues.map((issue) => ({ json: { id: issue.id } }));

// Filtra a issue individual (ja veio com journals) e prepara o payload
// para a revisao. Este node roda uma vez por issue.

// >>> AJUSTE AQUI: mesmo nome de projeto usado no Workflow 2.
const PROJECT_NAME = "NOME_DO_SEU_PROJETO_NO_LOVABLE";

const issue = $input.first().json.issue;
if (!issue) return [];

// Seguranca extra: revalida no codigo, nao confia so no filtro da URL.
if (issue.status.id !== 6) return [];

// Pega a ultima nota HUMANA (ignora notas que a propria automacao gerou,
// senao a revisao acabaria comparando o projeto contra o proprio resumo
// da IA em vez dos requisitos aprovados de verdade).
const AUTOMATION_NOTE_PREFIX = "Resultado automatizado do Workflow";
const journals = issue.journals || [];
const notesJournals = journals.filter(
  (j) => j.notes && j.notes.trim().length > 0 && !j.notes.trim().startsWith(AUTOMATION_NOTE_PREFIX)
);
const latestNote = notesJournals.length
  ? notesJournals[notesJournals.length - 1].notes
  : null;

if (!latestNote) return [];

return [
  {
    json: {
      issue_id: issue.id,
      project_name: PROJECT_NAME,
      title: issue.subject,
      requirements: latestNote,
    },
  },
];

// Interpreta a resposta do endpoint /lovable/review e monta o payload de
// atualizacao do Redmine.

const STATUS_MAP = {
  "New": 1,
  "Under Analysis": 2,
  "Artifacts Generated": 3,
  "Waiting for Artifact Approval": 4,
  "Under Development": 5,
  "Waiting for Tests": 6,
  "Under Testing": 7,
  "Waiting for Tests Approval": 8,
  "Ready for Publishing": 9,
  "Published": 10,
  "Automation Error": 11,
};

const item = $input.first().json;
const issueId = item.issue_id;
const worker = item; // resposta do worker ja vem "achatada" no body

const approved = worker.approved === true;
const summary = worker.summary || "(sem summary retornado pelo worker)";
const concerns = Array.isArray(worker.concerns) ? worker.concerns : [];
const feedback = worker.feedback_for_developer || "";
const warnings = Array.isArray(worker.warnings) ? worker.warnings : [];
const nextStatusName = worker.recommended_status || null;

let statusId = nextStatusName ? STATUS_MAP[nextStatusName] : undefined;
if (statusId === undefined || statusId === null) {
  // Rede de seguranca: se o Claude nao devolveu um status valido, usa um
  // default seguro em vez de deixar a issue parada.
  statusId = approved ? STATUS_MAP["Waiting for Tests Approval"] : STATUS_MAP["Under Development"];
}
if (worker.error) {
  statusId = STATUS_MAP["Automation Error"];
}

const notesLines = [
  `Resultado automatizado do Workflow 3 (Revisao via Claude Code + Lovable MCP):`,
  ``,
  `Aprovado: ${approved}`,
  `Resumo: ${summary}`,
];

if (concerns.length) {
  notesLines.push(``, `Pontos de atencao:`, ...concerns.map((c) => `- ${c}`));
}
if (!approved && feedback) {
  notesLines.push(``, `Ajustes necessarios (para o proximo ciclo de desenvolvimento):`, feedback);
}
if (warnings.length) {
  notesLines.push(``, `Avisos:`, ...warnings.map((w) => `- ${w}`));
}
if (worker.error) {
  notesLines.push(``, `Erro do worker: ${worker.error}`);
}

return [
  {
    json: {
      issue_id: issueId,
      status_id: statusId,
      notes: notesLines.join("\n"),
    },
  },
];

// Verifica a trava GLOBAL (Data Table "automation_lock", linha lock_name="global").
// Diferente da trava por chamado (campo "Automation Status" no Redmine, que
// impede a MESMA issue ser pega duas vezes) -- esta impede que QUALQUER
// combinacao dos workflows 1/2/3 rode ao mesmo tempo, ja que todos
// compartilham o mesmo worker/sessao do Claude Code conectada ao Lovable.

const LOCK_TIMEOUT_MINUTES = 30; // bem maior que qualquer timeout de worker configurado

const row = $input.first().json;
const status = row.status || "idle";
const lockedAt = row.locked_at || "";

if (status === "running" && lockedAt) {
  const lockAgeMinutes = (Date.now() - new Date(lockedAt).getTime()) / 60000;
  if (!isNaN(lockAgeMinutes) && lockAgeMinutes < LOCK_TIMEOUT_MINUTES) {
    return []; // outro workflow esta rodando agora -- para aqui, nada foi adquirido
  }
  // trava velha demais (execucao anterior travou/crashou sem liberar) -- segue e assume
}

return [{ json: { proceed: true } }];
